window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b095c4ae5c3d972c"]={"versions": [{"id": "FIG-b095c4ae5c3d972c", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Konfigurationsspezifikation (Parameter-Konfigurationsmodell) des AUTOSAR Diagnostic Communication Manager (DCM), spezifisch für das Submodul Diagnostic Service Processing (DSP) im Kontext des UDS-Dienstes ECUReset (0x11). Das Diagramm trägt das Paket- bzw. Klassen-Präfix <code>class DcmDspEcuReset</code> und wird von der normativen Anforderungsbox <code>Dcm260</code> begleitet.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell definiert folgende Konfigurationscontainer und Referenzen:</p>\n<ul class=\"fig-list\"><li><code>DcmDsp</code> (<code>ParamConfContainerDef</code>): Übergeordneter Container mit Kardinalität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>.\n</li><li><code>DcmDspEcuReset</code> (<code>ParamConfContainerDef</code>): Über die Kompositionsbeziehung <code>+subContainer</code> in <code>DcmDsp</code> eingebettet, Kardinalität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li><li><code>DcmDspEcuResetSecurityLevelRef</code> (<code>ReferenceParamDef</code>): Per Komposition (<code>+reference</code>) an <code>DcmDspEcuReset</code> angebunden; Kardinalität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>. Zeigt über die geradlinige Referenzbeziehung <code>+destination</code> auf den Zielcontainer <code>DcmDspSecurityRow</code> (<code>ParamConfContainerDef</code>, Kardinalität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 31</code>).\n</li><li><code>DcmDspEcuResetSessionRef</code> (<code>ReferenceParamDef</code>): Per Komposition (<code>+reference</code>) an <code>DcmDspEcuReset</code> angebunden; Kardinalität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>. Zeigt über die Referenzbeziehung <code>+destination</code> auf den Zielcontainer <code>DcmDspSessionRow</code> (<code>ParamConfContainerDef</code>, Kardinalität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 31</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell stellt das Diagramm keinen Laufzeit- oder Sequenzablauf dar. Das Schema legt fest, unter welchen Sicherheitsstufen (<code>SecurityLevel</code>) und Diagnose-Sitzungen (<code>Session</code>) die Ausführung des Dienstes ECUReset (0x11) durch den DCM zur Laufzeit zulässig ist.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>Dcm260</code> gilt: „The DCM module shall implement the UDS Service ECUReset (0x11) for the resetType=hardReset“. Für Entwickler bedeutet dies:</p>\n<ul class=\"fig-list\"><li>Die DCM-Implementierung muss den UDS-Dienst 0x11 verbindlich für den Subfunktions-Typ <code>hardReset</code> unterstützen.\n</li><li>Jeder konfigurierte <code>DcmDspEcuReset</code>-Container muss mindestens eine Referenz auf eine Sicherheitsstufe (<code>DcmDspSecurityRow</code>) und mindestens eine Referenz auf eine Sitzung (<code>DcmDspSessionRow</code>) enthalten (<code>lowerMultiplicity = 1</code>), kann jedoch mehreren Sicherheitsstufen und Sitzungen zugeordnet werden (<code>upperMultiplicity = *</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6b45b281a8373dec", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">null</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">null</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">null</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>Dcm260</code> gilt: „The DCM module shall implement the UDS Service ECUReset (0x11).“. Für Entwickler bedeutet dies:</p>\n<ul class=\"fig-list\"><li>Die Implementierung des UDS-Dienstes 0x11 durch das DCM-Modul ist normativ vorgeschrieben, ohne dass die Anforderung im Diagramm auf einen spezifischen <code>resetType</code> (wie <code>hardReset</code>) eingeschränkt ist.\n</li><li>Jeder konfigurierte <code>DcmDspEcuReset</code>-Container muss mindestens eine Referenz auf eine Sicherheitsstufe (<code>DcmDspSecurityRow</code>) und mindestens eine Referenz auf eine Sitzung (<code>DcmDspSessionRow</code>) enthalten (<code>lowerMultiplicity = 1</code>), kann jedoch mehreren Sicherheitsstufen und Sitzungen zugeordnet werden (<code>upperMultiplicity = *</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b095c4ae5c3d972c", "to": "FIG-6b45b281a8373dec", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Anforderungstext <code>Dcm260</code>: Die Einschränkung „for the resetType=hardReset“ wurde gestrichen; der Text lautet nun allgemein „The DCM module shall implement the UDS Service ECUReset (0x11).“.\n</li></ul>"}]};
